	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeDeleteReferenceObserve53.cls"), "@IsTest private class GladeDeleteReferenceObserve53 {\n private static User otherUser(){return new User(Alias='refdel',Email='refdel@example.invalid',EmailEncodingKey='UTF-8',LastName='OwnedReference',LanguageLocaleKey='en_US',LocaleSidKey='en_US',ProfileId=UserInfo.getProfileId(),TimeZoneSidKey='America/Los_Angeles',UserName='refdel.'+UserInfo.getOrganizationId()+'.'+String.valueOf(DateTime.now().getTime())+'@example.invalid');}\n private static Contact contact(){Account a=new Account(Name='owned-household');insert a;Contact c=new Contact(LastName='owned-reference',AccountId=a.Id);insert c;return c;}\n private static void finish(String caseName){System.assert(GladeDeleteReference53.rows.size()>0,'Observations missing');String text=JSON.serialize(GladeDeleteReference53.rows);System.assert(text.length()<2900,'Observation exceeds bound');verify(caseName,text);}\n @IsTest static void setNullThenSparseUpdate(){Contact c=contact();Test.startTest();GladeDeleteReference53.run(c.Id,false,false);Test.stopTest();finish('setNullThenSparseUpdate');}\n @IsTest static void deleteTriggerClearThenSparseUpdate(){Contact c=contact();Test.startTest();GladeDeleteReference53.run(c.Id,true,false);Test.stopTest();finish('deleteTriggerClearThenSparseUpdate');}\n @IsTest static void selectedViewAfterParentDelete(){Contact c=contact();Test.startTest();GladeDeleteReference53.run(c.Id,false,true);Test.stopTest();finish('selectedViewAfterParentDelete');}\n @IsTest static void convertedOtherUserDeleteReference(){\n  Id owner=UserInfo.getUserId();LeadStatus converted=[SELECT MasterLabel FROM LeadStatus WHERE IsConverted=true LIMIT 1];Lead lead=new Lead(FirstName='Owned',LastName='Reference',Company='owned-reference-company',OwnerId=owner,Status=converted.MasterLabel);insert lead;\n  System.runAs(otherUser()){Test.startTest();try{Database.LeadConvert request=new Database.LeadConvert();request.setLeadId(lead.Id);request.setOwnerId(owner);request.setConvertedStatus(converted.MasterLabel);request.setDoNotCreateOpportunity(true);Database.LeadConvertResult result=Database.convertLead(request);\n   GladeDeleteReference53.rows.add(new Map<String,Object>{'p'=>'conversion','success'=>result.isSuccess(),'contactAssigned'=>result.getContactId()!=null});if(result.isSuccess()&&result.getContactId()!=null)GladeDeleteReference53.run(result.getContactId(),true,false);\n  }catch(Exception e){GladeDeleteReference53.error('conversion',e);}Test.stopTest();}finish('convertedOtherUserDeleteReference');\n }\n private static void verify(String caseName,String text){\n  Map<String,Object> expectedByCase=(Map<String,Object>)JSON.deserializeUntyped('{\"setNullThenSparseUpdate\":[{\"p\":\"insert-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"assign\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"assigned\",\"description\":null,\"refMatch\":true,\"refNull\":false,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"delete-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"delete-return\",\"returned\":true},{\"p\":\"deleted\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"insert-return\",\"idAssigned\":true},{\"p\":\"controller-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"selected-view\",\"available\":true,\"refMatch\":true},{\"p\":\"sparse-write\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"controller-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}],\"deleteTriggerClearThenSparseUpdate\":[{\"p\":\"insert-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"assign\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"assigned\",\"description\":null,\"refMatch\":true,\"refNull\":false,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"delete-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"clear\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"cleared\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"delete-return\",\"returned\":true},{\"p\":\"deleted\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"insert-return\",\"idAssigned\":true},{\"p\":\"controller-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"selected-view\",\"available\":true,\"refMatch\":true},{\"p\":\"sparse-write\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"controller-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}],\"selectedViewAfterParentDelete\":[{\"p\":\"insert-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"assign\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"assigned\",\"description\":null,\"refMatch\":true,\"refNull\":false,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"delete-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"delete-return\",\"returned\":true},{\"p\":\"deleted\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"insert-return\",\"idAssigned\":true},{\"p\":\"controller-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"selected-view\",\"available\":true,\"refMatch\":true},{\"p\":\"stale-write\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"controller-after\",\"description\":\"owned-after\",\"refMatch\":true,\"refNull\":false,\"deleted\":true,\"all\":1,\"active\":0}],\"convertedOtherUserDeleteReference\":[{\"p\":\"conversion\",\"success\":true,\"contactAssigned\":true},{\"p\":\"insert-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"assign\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"assigned\",\"description\":null,\"refMatch\":true,\"refNull\":false,\"deleted\":false,\"all\":1,\"active\":1},{\"p\":\"delete-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"clear\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"cleared\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"delete-return\",\"returned\":true},{\"p\":\"deleted\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"insert-return\",\"idAssigned\":true},{\"p\":\"controller-entry\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"selected-view\",\"available\":true,\"refMatch\":true},{\"p\":\"sparse-write\",\"results\":[{\"errors\":[],\"ok\":true}]},{\"p\":\"controller-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}]}');\n  System.assert(expectedByCase.containsKey(caseName),'Bound expected case missing');\n  compare(expectedByCase.get(caseName),JSON.deserializeUntyped(text),'rows');\n }\n private static void compare(Object expected,Object actual,String path){\n  if(expected instanceof Map<String,Object>){Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;System.assertEquals(want.keySet(),got.keySet(),path+' keys');for(String key:want.keySet())compare(want.get(key),got.get(key),path+'.'+key);}\n  else if(expected instanceof List<Object>){List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;System.assertEquals(want.size(),got.size(),path+' size');for(Integer i=0;i<want.size();i++)compare(want[i],got[i],path+'['+i+']');}\n  else System.assertEquals(expected,actual,path);\n }\n}\n")
